export const BODY: string = "\n<p>فوٹو فلٹر ایک ہی کلک میں تصویر کا مزاج بدل دیتا ہے۔ رنگ گرم ہو جاتے ہیں، منظر پرانا لگنے لگتا ہے، یا تصویر سیاہ سفید میں بدل کر زیادہ ڈرامائی ہو جاتی ہے۔</p>\n<p>فلٹر دراصل رنگوں، روشنی اور تضاد پر پہلے سے طے شدہ تبدیلیوں کا مجموعہ ہے۔ ہر فلٹر ایک خاص احساس کے لیے بنایا گیا ہے، اور درست فلٹر تصویر کی کہانی کو مضبوط کرتا ہے، جبکہ غلط فلٹر اسے کمزور کر دیتا ہے۔</p>\n<p>یہ رہنما گیارہ فلٹر انداز، ان کی شدت، پورٹریٹ اور مناظر کے لیے انتخاب، اور عام غلطیوں کی وضاحت کرتا ہے۔ آزمانے کے لیے <a href=\"/ur/tasveer-filters/\">امیج فلٹرز</a> کھولیں اور اپنی تصویر پر فلٹر لگائیں۔</p>\n<h2 id=\"what-filters-do\">فوٹو فلٹر اصل میں کیا کرتے ہیں</h2>\n<p>فلٹر تصویر کے ہر پکسل کے رنگ اور روشنی کو ایک مقررہ اصول سے بدلتا ہے۔ کچھ فلٹر رنگوں کو گرم کرتے ہیں، کچھ تضاد بڑھاتے ہیں، اور کچھ رنگوں کو مکمل طور پر ہٹا دیتے ہیں۔</p>\n<p>فلٹر نئی تفصیل پیدا نہیں کرتا، بلکہ موجودہ تفصیل کو نئے انداز میں دکھاتا ہے۔ اسی لیے اچھی روشنی والی تصویر پر فلٹر اچھا لگتا ہے، جبکہ خراب تصویر پر فلٹر صرف خرابی کو نمایاں کرتا ہے۔</p>\n<h2 id=\"eleven-filter-styles\">گیارہ فلٹر انداز</h2>\n<p>ٹول میں گیارہ انداز ہیں، جن میں ونٹیج، سیپیا، گرے اسکیل، نوئر، میٹ فیڈ، گولڈن آور، گرم، ٹھنڈا اور انورٹ شامل ہیں۔ ہر انداز کا اپنا رنگ مزاج اور تضاد کا توازن ہے۔</p>\n<p>اندازوں کو ایک ایک کر کے آزمانا بہتر ہے، کیونکہ نام سے اندازہ لگانا مشکل ہوتا ہے۔ ایک ہی تصویر پر تین چار فلٹر لگا کر دیکھیں، پھر وہ چنیں جو موضوع کے احساس سے ملتا ہو۔</p>\n<h2 id=\"filter-intensity\">فلٹر کی شدت: 0 فیصد سے 100 فیصد تک</h2>\n<p>شدت کا سلائیڈر طے کرتا ہے کہ فلٹر کتنا مضبوط لگے گا۔ 100 فیصد پر فلٹر پورا اثر دکھاتا ہے، جبکہ 30 فیصد پر صرف ہلکا سا رنگ بدلتا ہے۔</p>\n<p>اکثر بہترین نتیجہ درمیانی شدت پر ملتا ہے۔ مکمل شدت ڈرامائی ہو سکتی ہے، مگر ہلکی شدت تصویر کو قدرتی رکھتے ہوئے مزاج بدل دیتی ہے۔</p>\n<h2 id=\"vintage-default\">ونٹیج پہلے سے کیوں منتخب ہوتا ہے</h2>\n<p>ٹول ونٹیج فلٹر سے شروع ہوتا ہے، کیونکہ یہ سب سے زیادہ پسند کیا جانے والا عام انداز ہے۔ ونٹیج رنگوں کو نرم کرتا ہے، تضاد ہلکا کرتا ہے اور تصویر کو پرانی یاد کا احساس دیتا ہے۔</p>\n<p>یہ پہلے سے طے شدہ انتخاب صرف شروعات ہے، آپ کو اسی پر رکنا نہیں ہے۔ اگر تصویر کو تازہ اور صاف نظر آنا چاہیے تو ونٹیج ہٹا کر دوسرا انداز آزمائیں۔</p>\n<h2 id=\"grayscale-vs-noir\">گرے اسکیل بمقابلہ بلیک اینڈ وائٹ نوئر</h2>\n<p>گرے اسکیل رنگ ہٹا کر نرم سیاہ سفید تصویر بناتا ہے، جس میں درمیانی سرمئی رنگ بہت ہوتے ہیں۔ نوئر زیادہ سخت ہے: گہرے سیاہ، چمکتی سفید اور تیز تضاد، جو ڈرامائی پورٹریٹ کے لیے بنایا گیا ہے۔</p>\n<p>گرے اسکیل پرانی دستاویزی تصویر جیسا لگتا ہے، جبکہ نوئر فلمی اور پراسرار محسوس ہوتا ہے۔ موضوع کے مزاج کے مطابق چنیں، نہ کہ صرف نام کے مطابق۔</p>\n<h2 id=\"sepia-vintage-matte-golden\">سیپیا، ونٹیج، میٹ فیڈ اور گولڈن آور</h2>\n<p>سیپیا تصویر کو بھورے سنہری رنگ میں رنگ دیتا ہے، جیسے انیسویں صدی کی تصویر۔ ونٹیج اس سے نرم ہے اور رنگوں کو مدھم کرتا ہے، جبکہ میٹ فیڈ کالے رنگ کو سرمئی کر کے جدید نرم احساس دیتا ہے۔</p>\n<p>گولڈن آور سورج غروب ہونے کی سنہری روشنی کی نقل کرتا ہے، جو مناظر اور پورٹریٹ دونوں میں گرمی بھرتا ہے۔ یہ چاروں انداز ایک دوسرے کے قریب ہیں، مگر ہر ایک کا رنگ درجہ حرارت الگ ہے۔</p>\n<h2 id=\"warm-vs-cool\">گرم بمقابلہ ٹھنڈے فلٹر</h2>\n<p>گرم فلٹر سرخ اور پیلے رنگ بڑھاتے ہیں، جس سے تصویر دھوپ والی اور خوشگوار لگتی ہے۔ ٹھنڈے فلٹر نیلے رنگ بڑھاتے ہیں، جس سے تصویر پرسکون، صبح والی یا پیشہ ورانہ لگتی ہے۔</p>\n<p>گرم انداز کھانے، شادی اور غروب آفتاب کے لیے اچھا ہے، جبکہ ٹھنڈا انداز برف، سمندر اور کاروباری تصویروں کے لیے موزوں ہے۔ غلط درجہ حرارت تصویر کا احساس ہی بدل دیتا ہے۔</p>\n<h2 id=\"invert-filter\">انورٹ فلٹر</h2>\n<p>انورٹ فلٹر ہر رنگ کو اس کے الٹ میں بدل دیتا ہے: سفید کالا، کالا سفید، اور نیلا نارنجی بن جاتا ہے۔ یہ عام تصویروں کے لیے نہیں، بلکہ تجرباتی اور فنکارانہ اثر کے لیے ہے۔</p>\n<p>انورٹ سے چھپی ہوئی تفصیل بھی نظر آ سکتی ہے، جیسے میڈیکل یا سائنسی تصویر میں۔ عام پورٹریٹ پر انورٹ لگانے سے چہرہ اجنبی اور غیر فطری لگنے لگتا ہے۔</p>\n<h2 id=\"hold-to-view-original\">اصل دیکھنے کے لیے دبائے رکھیں</h2>\n<p>اصل دیکھنے کی خصوصیت آپ کو فلٹر لگی تصویر اور اصل تصویر کے درمیان تیزی سے موازنہ کرنے دیتی ہے۔ بٹن دبائے رکھیں تو اصل نظر آتی ہے، چھوڑیں تو فلٹر واپس آ جاتا ہے۔</p>\n<p>یہ موازنہ بہت اہم ہے، کیونکہ فلٹر لگاتے وقت آنکھ آہستہ آہستہ نئے رنگوں کی عادی ہو جاتی ہے۔ اصل دیکھ کر ہی پتا چلتا ہے کہ فلٹر نے تصویر بہتر کی ہے یا بگاڑی ہے۔</p>\n<h2 id=\"side-by-side-compare\">ساتھ ساتھ موازنہ</h2>\n<p>ساتھ ساتھ موازنے میں اصل اور فلٹر لگی تصویر ایک ساتھ دکھائی دیتی ہیں، جس سے فرق صاف نظر آتا ہے۔ یہ خاص طور پر اس وقت کام آتا ہے جب شدت کم ہو اور فرق باریک ہو۔</p>\n<p>موازنہ کرتے وقت تصویر کے تین حصے دیکھیں: چہرے کی جلد، آسمان اور سائے۔ اگر تینوں میں فلٹر اچھا لگے تو انتخاب درست ہے، ورنہ شدت کم کریں یا انداز بدلیں۔</p>\n<h2 id=\"filters-for-portraits\">پورٹریٹ کے لیے فلٹر</h2>\n<p>پورٹریٹ میں جلد کا رنگ سب سے اہم ہے، اس لیے نرم اور گرم فلٹر بہتر ہوتے ہیں۔ ونٹیج یا گولڈن آور جلد کو صحت مند چمک دیتا ہے، جبکہ سخت تضاد والے فلٹر جلد کی خامیوں کو نمایاں کر دیتے ہیں۔</p>\n<p>پورٹریٹ پر سیاہ سفید بھی اچھا لگتا ہے، مگر نوئر کے بجائے نرم گرے اسکیل چنیں، تاکہ چہرے کی نرمی برقرار رہے اور جھریاں ضرورت سے زیادہ نمایاں نہ ہوں۔</p>\n<h2 id=\"filters-for-landscapes\">مناظر کے لیے فلٹر</h2>\n<p>مناظر میں آسمان اور ہریالی اہم ہوتی ہے، اس لیے وہ فلٹر اچھے ہیں جو نیلے اور سبز رنگ کو گہرا کریں۔ گولڈن آور پہاڑوں اور سمندر کو سنہری روشنی دیتا ہے، جبکہ میٹ فیڈ دھند والے منظر کو نرم کرتا ہے۔</p>\n<p>منظر پر زیادہ شدت سے رنگ غیر فطری ہو جاتے ہیں، خاص طور پر گھاس اور درخت۔ شدت کو درمیان میں رکھیں تاکہ منظر خوبصورت لگے، مگر اصلی بھی رہے۔</p>\n<h2 id=\"consistent-look\">مستقل انداز چننا</h2>\n<p>اگر آپ کی فیڈ یا البم میں سب تصویریں ایک ہی انداز میں ہوں تو وہ پیشہ ورانہ لگتی ہیں۔ ایک فلٹر اور ایک شدت طے کریں اور سب تصویروں پر وہی استعمال کریں۔</p>\n<p>مستقل مزاجی کا مطلب ہر تصویر پر ایک ہی فلٹر زبردستی لگانا نہیں۔ مختلف روشنی والی تصویروں میں شدت تھوڑی کم زیادہ ہو سکتی ہے، مگر بنیادی انداز ایک ہی رہنا چاہیے۔</p>\n<h2 id=\"formats-and-export\">فارمیٹ اور برآمد</h2>\n<p>فلٹر لگانے کے بعد تصویر کو اسی فارمیٹ میں محفوظ کرنا بہتر ہے جس میں وہ تھی، تاکہ شفافیت یا معیار نہ بدلے۔ PNG شفافیت بچاتا ہے، JPG چھوٹی فائل دیتا ہے۔</p>\n<p>برآمد سے پہلے نتیجہ کو مکمل سائز میں دیکھیں، کیونکہ چھوٹے پیش منظر پر فلٹر ہلکا لگتا ہے اور بڑی تصویر پر مضبوط۔ ڈاؤن لوڈ کے بعد اصل فائل بھی محفوظ رکھیں۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: بغیر اپ لوڈ کے فلٹر لگانا</h2>\n<p>فلٹر آپ کے براؤزر میں لگتا ہے، تصویر کسی سرور پر نہیں جاتی۔ یہ نجی اور خاندانی تصویروں کے لیے بہت اہم ہے، کیونکہ فائل آپ کے آلے سے باہر نہیں نکلتی۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔ کوئی اکاؤنٹ نہیں بنتا اور کوئی نقل محفوظ نہیں رہتی، اس لیے ذاتی تصویریں بے فکر ہو کر ایڈٹ کریں۔</p>\n<h2 id=\"common-mistakes\">فلٹر استعمال کرتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی شدت کو 100 فیصد پر چھوڑ دینا ہے، جس سے رنگ غیر فطری ہو جاتے ہیں۔ دوسری غلطی ہر تصویر پر الگ فلٹر لگانا ہے، جس سے فیڈ بے ترتیب لگتی ہے۔</p>\n<p>تیسری غلطی فلٹر سے خراب تصویر ٹھیک کرنے کی کوشش ہے۔ دھندلی یا کم روشنی والی تصویر پر فلٹر خرابی چھپا نہیں سکتا، اس لیے پہلے روشنی اور تیزرفتاری درست کریں۔</p>\n<h2 id=\"filters-for-travel\">سفر کی تصویروں کے لیے فلٹر</h2>\n<p>سفر کی تصویروں میں جگہ کا احساس اہم ہوتا ہے، اس لیے وہ فلٹر چنیں جو اس جگہ کی روشنی سے ملتا ہو۔ ساحل کے لیے گرم، پہاڑوں کے لیے ٹھنڈا اور شہر کے لیے میٹ فیڈ اچھا رہتا ہے۔</p>\n<p>سفر کے البم میں ایک ہی انداز رکھیں تاکہ مختلف شہروں کی تصویریں بھی ایک کہانی لگیں۔ ہر شہر پر نیا فلٹر آزمانے سے البم بکھرا ہوا محسوس ہوتا ہے۔ فلٹرز کا موازنہ <a href=\"/ur/blog/photo-filters-muqabla/\">فلٹرز کا موازنہ</a> میں اور عملی مراحل <a href=\"/ur/blog/photo-par-filters-kaise-lagayein/\">فوٹو فلٹر کیسے لگائیں</a> میں دیکھیں۔ رنگوں کی باریک ایڈیٹنگ کے لیے <a href=\"/ur/tasveer-ki-saturation-badlein/\">امیج سیچوریشن ایڈیٹر</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"پورٹریٹ کے لیے کون سا فوٹو فلٹر بہترین ہے؟","answer":"نرم اور گرم فلٹر بہترین ہیں، جیسے ونٹیج یا گولڈن آور، کیونکہ یہ جلد کو صحت مند چمک دیتے ہیں۔ سخت تضاد والے فلٹر جلد کی خامیوں کو نمایاں کر دیتے ہیں، اس لیے ان سے بچیں۔"},{"question":"فلٹر کی شدت کا سلائیڈر کیا کرتا ہے؟","answer":"شدت طے کرتی ہے کہ فلٹر کتنا مضبوط لگے گا۔ 100 فیصد پر پورا اثر ہوتا ہے، جبکہ 30 فیصد پر صرف ہلکا سا رنگ بدلتا ہے۔ اکثر بہترین نتیجہ درمیانی شدت پر ملتا ہے۔"},{"question":"ٹول ونٹیج منتخب کر کے کیوں شروع ہوتا ہے؟","answer":"ونٹیج سب سے زیادہ پسند کیا جانے والا عام انداز ہے، اس لیے اسے شروعاتی انتخاب بنایا گیا ہے۔ یہ صرف شروعات ہے، آپ کسی بھی وقت دوسرا انداز چن سکتے ہیں۔"},{"question":"کیا میں ایک ہی تصویر پر دو فلٹر لگا سکتا ہوں؟","answer":"ایک وقت میں ایک ہی فلٹر لگتا ہے۔ اگر دو اثرات چاہییں تو پہلے ایک فلٹر لگا کر محفوظ کریں، پھر محفوظ شدہ تصویر پر دوسرا فلٹر لگائیں۔"},{"question":"کیا فلٹر تصویر کی ریزولوشن بدلتے ہیں؟","answer":"نہیں، فلٹر صرف رنگ اور روشنی بدلتے ہیں، پکسلز کی تعداد وہی رہتی ہے۔ تصویر کا سائز اور تیزرفتاری نہیں بدلتی، صرف اس کا انداز بدلتا ہے۔"},{"question":"کیا براؤزر ٹول میں ذاتی تصویر پر فلٹر لگانا محفوظ ہے؟","answer":"جی ہاں، فلٹر آپ کے براؤزر میں لگتا ہے اور تصویر کسی سرور پر نہیں جاتی۔ براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔"}];
